# ---------------------------------------------------------------------------
# Transferred comments from alpha source
# ---------------------------------------------------------------------------

# CMLOGO.ROU
INLINE  8000  CM_LOGO - Codemasters logo intro routine
INLINE  8008  Clear zero page and fill sprite page ($0300) with $FF
INLINE  803E  CLS - clear nametable
INLINE  8051  Print 'AB' (Codemasters logo tilemap)
INLINE  806D  'AB' attribute patch
INLINE  8095  SFX setup - silence all APU channels
INLINE  80A4  Main loop - wait for vblank then process frame
INLINE  80AF  Noise freq - alternates each frame
INLINE  80E6  Fading saw ping - volume ramps down over time
INLINE  8104  Pre-circle: rising saw waves on pulse channels 1+2
INLINE  8123  Timeout check - exit after animation completes
INLINE  814A  Timeout: disable PPU, silence APU, set flags, return to game
INLINE  815E  CM_VBLANK - wait for next frame, update PPU during vblank
INLINE  8166  Upload palette - 8 colors repeated 4 times to fill 32 entries
INLINE  818A  Colour fade-in: gradually brighten logo palette over time
INLINE  81CD  CM_STRIP - write one more column of 'MASTERS' characters per frame
INLINE  81F9  CM_CODEWRITE - write 'Code' as background tiles when scrolling done
INLINE  8260  Vertical scroll - logo scrolls down then stops
INLINE  8298  CM_CODEPLOT - plot sprite bitmap from codemap data
INLINE  82E1  CM_QUART - display circle quarter sprites with 4-way symmetry
INLINE  8423  CM_CHARACTERS - decompress PP1 character data to CHR RAM

# SMILEY.ROU
INLINE  8906  SMILEY self-test - ROM/RAM verification by Jon Menzies and Gavin Raeburn
INLINE  8949  Test 2 - Char RAM test: write/read incrementing and complement patterns
INLINE  89E6  TEST2_SET - set VRAM address to $0000 for CHR RAM access
INLINE  89E8  ROM_CHECK - source of relocating code copied to ZP for self-modifying execution
INLINE  89F3  KEYPAD - read controller 1 into pad1 variable
INLINE  8A08  ROM checksum loop: checksums all banks, compares against expected values
INLINE  8A68  ROM check failed: set bit 2 in test_byte
INLINE  8AA2  Good face: green smiley ($55 checkerboard, $1A green background)
INLINE  8AA8  Bad face: red smiley ($AA inverse checkerboard, $16 red background)
INLINE  8AAC  SHOW_FACE - A=bg colour, X=face mask. Writes diagnostic result to $4400
INLINE  8ACB  Download 1 solid character (16 bytes of $FF to CHR RAM)
INLINE  8ADA  Print face - fill nametable with incrementing tiles
INLINE  8AEE  Write face attribute data masked by pass/fail pattern
INLINE  8B1D  Wait a few seconds then turn screen off

# ROM checksum page boundaries (referenced by smiley_here/a/b/c)
RENAME  L9000  bank2_page_9000     ; ADC $9000,X checksum target
RENAME  LA000  bank2_page_a000     ; ADC $A000,X checksum target
RENAME  LB000  bank2_page_b000     ; ADC $B000,X checksum target
